import { createContext, useContext, useEffect, useMemo, useState } from 'react'
import { Navigate, NavLink, Outlet, Route, Routes, useLocation, useNavigate, useSearchParams } from 'react-router-dom'
import { Activity, ArrowDownLeft, ArrowDownToLine, Bell, Building2, CalendarDays, CircleDollarSign, ClipboardList, CreditCard, DoorOpen, FileBarChart2, FileCheck2, FileSpreadsheet, Home, LogOut, Menu, Plus, Search, Settings, ShieldCheck, Users, Wallet, X, Zap } from 'lucide-react'
import { Area, AreaChart, CartesianGrid, Cell, Pie, PieChart, ResponsiveContainer, Tooltip, XAxis, YAxis } from 'recharts'
import { api } from './api'
import type { Bill, Branding, Dashboard, Employee, Expense, Invoice, Payment, Role, Room, Student, User } from './types'

type AppContextValue = { user: User; branding: Branding; refreshBranding: () => Promise<void>; notify: (message: string) => void }
const AppContext = createContext<AppContextValue | null>(null)
const useApp = () => { const value = useContext(AppContext); if (!value) throw new Error('App context missing'); return value }
const fallbackBranding: Branding = { hostelName: 'INDUS HOSTEL SERVICE BADIN' }
const icons: Record<string, typeof Home> = { dashboard: Home, students: Users, rooms: DoorOpen, fees: CreditCard, payments: FileCheck2, expenses: CircleDollarSign, bills: CalendarDays, staff: Building2, withdrawals: ArrowDownLeft, reports: FileBarChart2, accounts: ShieldCheck, audit: ClipboardList, settings: Settings, notifications: Bell }

export default function App() {
  const [user, setUser] = useState<User | null>(null)
  const [branding, setBranding] = useState<Branding>(fallbackBranding)
  const [loading, setLoading] = useState(true)
  const [toast, setToast] = useState('')
  const location = useLocation()
  const navigate = useNavigate()

  const refreshBranding = async () => { try { setBranding(await api.get<Branding>('/api/branding')) } catch { setBranding(fallbackBranding) } }
  const notify = (message: string) => { setToast(message); window.setTimeout(() => setToast(''), 3200) }
  useEffect(() => { void Promise.all([refreshBranding(), api.get<User>('/api/auth/me').then(setUser).catch(() => setUser(null))]).finally(() => setLoading(false)) }, [])

  const login = async (email: string, password: string) => {
    const next = await api.post<User>('/api/auth/login', { email, password })
    setUser(next); navigate('/', { replace: true })
  }
  const logout = async () => { try { await api.post('/api/auth/logout') } finally { setUser(null); navigate('/login', { replace: true }) } }
  const context = useMemo(() => user ? { user, branding, refreshBranding, notify } : null, [user, branding])

  if (loading) return <div className="min-h-screen grid place-items-center text-sm text-slate-500">Loading hostel records…</div>
  return <AppContext.Provider value={context as AppContextValue}>
    <Routes>
      <Route path="/login" element={user ? <Navigate to="/" replace /> : <LoginPage branding={branding} onLogin={login} />} />
      <Route path="/reset-password" element={<PasswordResetPage />} />
      <Route path="/" element={user ? <Shell onLogout={logout} /> : <Navigate to="/login" replace state={{ from: location.pathname }} />}>
        <Route index element={<DashboardPage />} />
        <Route path="students" element={<StudentsPage />} />
        <Route path="rooms" element={user?.role === 'STUDENT' ? <Navigate to="/" replace /> : <RoomsPage />} />
        <Route path="fees" element={<FeesPage />} />
        <Route path="payments" element={<PaymentsPage />} />
        <Route path="expenses" element={user?.role === 'STUDENT' ? <Navigate to="/" replace /> : <ExpensesPage />} />
        <Route path="bills" element={user?.role === 'STUDENT' ? <Navigate to="/" replace /> : <BillsPage />} />
        <Route path="staff" element={user?.role === 'STUDENT' ? <Navigate to="/" replace /> : <StaffPage />} />
        <Route path="withdrawals" element={user?.role !== 'OWNER' ? <Navigate to="/" replace /> : <WithdrawalsPage />} />
        <Route path="reports" element={user?.role !== 'OWNER' ? <Navigate to="/" replace /> : <ReportsPage />} />
        <Route path="accounts" element={user?.role !== 'OWNER' ? <Navigate to="/" replace /> : <AccountsPage />} />
        <Route path="audit" element={user?.role !== 'OWNER' ? <Navigate to="/" replace /> : <AuditPage />} />
        <Route path="notifications" element={<NotificationsPage />} />
        <Route path="settings" element={user?.role !== 'OWNER' ? <Navigate to="/" replace /> : <SettingsPage />} />
        <Route path="*" element={<Navigate to="/" replace />} />
      </Route>
    </Routes>
    {toast && <div role="status" className="toast">{toast}</div>}
  </AppContext.Provider>
}

function linksFor(role: Role) {
  if (role === 'STUDENT') return [{ to: '/', label: 'My dashboard', key: 'dashboard' }, { to: '/fees', label: 'My fees', key: 'fees' }, { to: '/payments', label: 'Payment history', key: 'payments' }, { to: '/notifications', label: 'Notifications', key: 'notifications' }]
  const common = [{ to: '/', label: 'Dashboard', key: 'dashboard' }, { to: '/students', label: 'Students', key: 'students' }, { to: '/rooms', label: 'Rooms & beds', key: 'rooms' }, { to: '/fees', label: 'Fee records', key: 'fees' }, { to: '/payments', label: 'Payment review', key: 'payments' }, { to: '/expenses', label: 'Expenses', key: 'expenses' }, { to: '/bills', label: 'Utility bills', key: 'bills' }, { to: '/staff', label: 'Employees', key: 'staff' }]
  return role === 'OWNER' ? [...common, { to: '/withdrawals', label: 'Owner withdrawals', key: 'withdrawals' }, { to: '/reports', label: 'Reports', key: 'reports' }, { to: '/accounts', label: 'User access', key: 'accounts' }, { to: '/audit', label: 'Audit log', key: 'audit' }, { to: '/settings', label: 'Hostel settings', key: 'settings' }, { to: '/notifications', label: 'Notifications', key: 'notifications' }] : [...common, { to: '/notifications', label: 'Notifications', key: 'notifications' }]
}

function Shell({ onLogout }: { onLogout: () => void }) {
  const { user, branding } = useApp()
  const [open, setOpen] = useState(false)
  const links = linksFor(user.role)
  const roleLabel = user.role === 'OWNER' ? 'Owner panel' : user.role === 'MANAGER' ? 'Manager panel' : 'Student panel'
  return <div className="app-shell">
    <aside className="sidebar">
      <Brand branding={branding} compact />
      <div className="mt-9 mb-3 px-3 text-[10px] font-bold uppercase tracking-[.16em] text-slate-400">{roleLabel}</div>
      <nav className="grid gap-1">{links.map(item => { const Icon = icons[item.key] ?? Home; return <NavLink key={item.key} to={item.to} end={item.to === '/'} className={({ isActive }) => `nav-link ${isActive ? 'active' : ''}`}><Icon size={18} /><span className="nav-label">{item.label}</span></NavLink> })}</nav>
      <div className="mt-auto side-footer border-t border-white/10 pt-5">
        <div className="truncate px-3 text-sm font-semibold">{user.displayName}</div><div className="truncate px-3 pt-1 text-xs text-slate-400">{user.email}</div>
        <button className="nav-link mt-4 w-full" onClick={onLogout}><LogOut size={17} /><span className="nav-label">Sign out</span></button>
      </div>
    </aside>
    <main className="main-area">
      <header className="topbar">
        <div className="flex items-center gap-3"><button className="btn btn-muted !p-2 md:hidden" onClick={() => setOpen(!open)} aria-label="Toggle navigation"><Menu size={17} /></button><div className="md:hidden"><Brand branding={branding} /></div><div className="hidden md:block"><div className="text-xs text-slate-400">{roleLabel}</div><div className="text-sm font-semibold text-ink">{branding.hostelName}</div></div></div>
        <div className="flex items-center gap-3"><div className="hidden text-right sm:block"><div className="text-sm font-semibold">{user.displayName}</div><div className="text-xs text-slate-400">{user.role.toLowerCase()}</div></div><div className="grid h-9 w-9 place-items-center rounded-full bg-teal/10 text-sm font-bold text-teal">{user.displayName.split(' ').map(x=>x[0]).slice(0,2).join('').toUpperCase()}</div><button className="btn btn-muted !p-2 sm:hidden" onClick={onLogout} aria-label="Sign out"><LogOut size={16} /></button></div>
      </header>
      {open && <div className="fixed inset-0 z-40 bg-ink/30 md:hidden" onClick={() => setOpen(false)}><div className="h-full w-72 bg-ink p-5" onClick={e => e.stopPropagation()}><button onClick={() => setOpen(false)} className="mb-5 text-white"><X /></button><Brand branding={branding} compact />{links.map(item=>{const Icon=icons[item.key]??Home;return <NavLink onClick={()=>setOpen(false)} key={item.key} to={item.to} className="nav-link"><Icon size={17}/><span>{item.label}</span></NavLink>})}</div></div>}
      <div className="page-wrap"><Outlet /></div>
      <nav className="mobile-nav">{links.slice(0,4).map(item=>{const Icon=icons[item.key]??Home;return <NavLink key={item.key} to={item.to} end={item.to==='/'}><Icon size={18}/><span>{item.label.split(' ')[0]}</span></NavLink>})}</nav>
    </main>
  </div>
}

function Brand({ branding, compact = false }: { branding: Branding; compact?: boolean }) {
  return <div className={`flex min-w-0 items-center gap-3 ${compact ? 'px-2' : ''}`}>
    {branding.logoFileId ? <img src={`${api.base}/api/branding/logo`} alt="Official hostel logo" className="h-10 w-10 rounded-lg bg-white object-contain" /> : <div aria-hidden="true" className="h-1 w-1 shrink-0 rounded-full bg-gold" />}
    <div className={`${compact ? 'brand-label' : ''} min-w-0`}><div className={`truncate font-extrabold leading-tight ${compact ? 'text-[12px] text-white' : 'text-xs text-ink'}`}>{branding.hostelName}</div>{compact && <div className="mt-1 text-[10px] tracking-wide text-slate-400">HOSTEL MANAGEMENT</div>}</div>
  </div>
}

function LoginPage({ branding, onLogin }: { branding: Branding; onLogin: (email: string, password: string) => Promise<void> }) {
  const [email, setEmail] = useState('')
  const [password, setPassword] = useState('')
  const [error, setError] = useState('')
  const [busy, setBusy] = useState(false)
  const [reset,setReset]=useState(false)
  const submit = async (e: React.FormEvent) => { e.preventDefault(); setError(''); setBusy(true); try { await onLogin(email,password) } catch (err) { setError(err instanceof Error ? err.message : 'Unable to sign in') } finally { setBusy(false) } }
  return <div className="grid min-h-screen bg-white lg:grid-cols-[1fr_.9fr]">
    <div className="relative hidden overflow-hidden bg-ink p-12 text-white lg:flex lg:flex-col lg:justify-between"><div className="absolute -right-24 -top-20 h-[500px] w-[500px] rounded-full border border-white/10"/><div className="absolute -right-2 -top-2 h-[360px] w-[360px] rounded-full border border-white/10"/><div><Brand branding={branding} compact /><div className="mt-32 max-w-xl"><div className="mb-5 inline-flex items-center gap-2 rounded-full border border-white/20 px-3 py-1 text-xs text-slate-300"><ShieldCheck size={14}/> Private hostel operations</div><h1 className="text-5xl font-bold leading-[1.12]">A better way to manage <span className="text-gold">hostel life.</span></h1><p className="mt-6 max-w-md text-base leading-7 text-slate-300">One secure place for student stays, room availability, monthly fees, and hostel operations.</p></div></div><div className="text-xs text-slate-400">{branding.hostelName} · Badin</div></div>
    <div className="flex items-center justify-center px-6 py-12"><div className="w-full max-w-[410px]"><div className="mb-10 lg:hidden"><Brand branding={branding}/></div><div className="mb-8"><p className="text-xs font-bold uppercase tracking-[.16em] text-teal">Secure sign in</p><h2 className="mt-2 text-3xl font-bold text-ink">Welcome back</h2><p className="mt-2 text-sm text-slate-500">Enter your account details to continue.</p></div>
      <form onSubmit={submit} className="grid gap-5"><label className="grid gap-2 text-sm font-semibold">Email address<input autoComplete="username" type="email" className="field" value={email} onChange={e=>setEmail(e.target.value)} required /></label><label className="grid gap-2 text-sm font-semibold">Password<input autoComplete="current-password" type="password" className="field" value={password} onChange={e=>setPassword(e.target.value)} required /></label>{error&&<div role="alert" className="rounded-lg bg-red-50 px-3 py-2 text-sm text-red-700">{error}</div>}<button className="btn btn-primary mt-1 w-full py-3" disabled={busy}>{busy?'Signing in…':'Sign in'}</button></form>
      <button className="mt-4 text-xs font-semibold text-teal hover:underline" onClick={()=>setReset(true)}>Forgot password?</button>
      <div className="mt-8 border-t border-slate-100 pt-5 text-xs leading-5 text-slate-400">Access is limited to authorized Owner, Manager, and Student accounts.</div>
    </div></div>
    {reset&&<Modal title="Reset your password" onClose={()=>setReset(false)}><p className="mb-4 text-sm leading-6 text-slate-500">If an account matches this email and can receive messages, the system will email a one time reset link.</p><form onSubmit={async e=>{e.preventDefault();setBusy(true);setError('');try{await api.post('/api/auth/password-reset/request',{email});setReset(false);setError('If this account can receive email, reset instructions have been sent.')}catch(err){setError(errorText(err))}finally{setBusy(false)}}} className="grid gap-4"><Field label="Email address" required><input className="field" type="email" value={email} onChange={e=>setEmail(e.target.value)} required/></Field>{error&&<div role="status" className="text-xs text-slate-500">{error}</div>}<button className="btn btn-primary" disabled={busy}>{busy?'Sending…':'Send reset instructions'}</button></form></Modal>}
  </div>
}

function PasswordResetPage() {
  const [params]=useSearchParams();const [password,setPassword]=useState('');const [confirm,setConfirm]=useState('');const [busy,setBusy]=useState(false);const [message,setMessage]=useState('');const navigate=useNavigate();const token=params.get('token')??''
  const submit=async(e:React.FormEvent)=>{e.preventDefault();setMessage('');if(password!==confirm){setMessage('Passwords do not match');return}setBusy(true);try{await api.post('/api/auth/password-reset/confirm',{token,newPassword:password});setMessage('Password updated. You can sign in now.');window.setTimeout(()=>navigate('/login'),1200)}catch(err){setMessage(errorText(err))}finally{setBusy(false)}}
  return <div className="grid min-h-screen place-items-center bg-canvas p-5"><Card className="w-full max-w-md p-6"><Brand branding={fallbackBranding}/><h1 className="mt-8 text-2xl font-bold text-ink">Choose a new password</h1><p className="mt-2 text-sm leading-6 text-slate-500">Use at least 12 characters. The reset link expires after 30 minutes and can only be used once.</p><form className="mt-6 grid gap-4" onSubmit={submit}><Field label="New password" required><input className="field" type="password" minLength={12} autoComplete="new-password" value={password} onChange={e=>setPassword(e.target.value)} required/></Field><Field label="Confirm password" required><input className="field" type="password" minLength={12} autoComplete="new-password" value={confirm} onChange={e=>setConfirm(e.target.value)} required/></Field>{message&&<div role="status" className="text-sm text-slate-600">{message}</div>}<button className="btn btn-primary" disabled={busy||!token}>{busy?'Updating…':'Update password'}</button></form></Card></div>
}

function PageTitle({ eyebrow, title, subtitle, action }: { eyebrow?: string; title: string; subtitle?: string; action?: React.ReactNode }) { return <div className="mb-7 flex flex-wrap items-end justify-between gap-4"><div>{eyebrow&&<div className="mb-2 text-[10px] font-bold uppercase tracking-[.18em] text-teal">{eyebrow}</div>}<h1 className="text-2xl font-bold tracking-tight text-ink">{title}</h1>{subtitle&&<p className="mt-1.5 max-w-2xl text-sm text-slate-500">{subtitle}</p>}</div>{action}</div> }
function Card({ children, className = '' }: { children: React.ReactNode; className?: string }) { return <section className={`card ${className}`}>{children}</section> }
function CardHead({ title, subtitle, action }: { title: string; subtitle?: string; action?: React.ReactNode }) { return <div className="flex items-center justify-between gap-3 border-b border-slate-100 px-5 py-4"><div><h2 className="text-sm font-bold text-ink">{title}</h2>{subtitle&&<p className="mt-1 text-xs text-slate-400">{subtitle}</p>}</div>{action}</div> }
function Loading({ label = 'Loading records…' }: { label?: string }) { return <div className="p-9 text-center text-sm text-slate-400">{label}</div> }
function Empty({ title = 'No records yet', subtitle = 'Records will appear here when available.' }: { title?: string; subtitle?: string }) { return <div className="px-5 py-12 text-center"><div className="mx-auto grid h-11 w-11 place-items-center rounded-xl bg-slate-100 text-slate-400"><FileSpreadsheet size={19}/></div><div className="mt-3 text-sm font-semibold text-ink">{title}</div><div className="mt-1 text-xs text-slate-400">{subtitle}</div></div> }
function Status({ value }: { value: string }) { const text=value.replace(/_/g,' ').toLowerCase(); const cls=['paid','approved','active','sent','succeeded'].includes(text)?'pill-good':['pending','pending verification','upcoming','due','partially paid'].includes(text)?'pill-warn':['overdue','rejected','failed','inactive','reversed'].includes(text)?'pill-bad':'pill-neutral'; return <span className={`pill ${cls}`}>{text}</span> }
function money(value: unknown) { const n=Number(value??0);return `PKR ${new Intl.NumberFormat('en-PK',{maximumFractionDigits:0}).format(Number.isFinite(n)?n:0)}` }
function date(value: unknown) { if(!value)return '—'; const d=new Date(String(value));return Number.isNaN(d.getTime())?String(value):d.toLocaleDateString('en-PK',{day:'numeric',month:'short',year:'numeric'}) }
function dateMonth(value: string) { if(!value)return '—';const d=new Date(String(value).length===7?`${value}-01`:value);return Number.isNaN(d.getTime())?String(value):d.toLocaleDateString('en-PK',{month:'short',year:'numeric'}) }
function initialDate() { return new Date().toISOString().slice(0,10) }
function downloadBlob(blob: Blob,name: string) { const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(url) }
async function download(path: string,name: string) { const blob=await api.file(path);downloadBlob(blob,name) }
function Modal({ title, onClose, children, wide=false }: { title:string;onClose:()=>void;children:React.ReactNode;wide?:boolean }) { return <div className="fixed inset-0 z-50 grid place-items-center bg-ink/45 p-4" onClick={onClose}><div role="dialog" aria-modal="true" aria-label={title} className={`max-h-[90vh] w-full ${wide?'max-w-3xl':'max-w-lg'} overflow-y-auto rounded-2xl bg-white shadow-2xl`} onClick={e=>e.stopPropagation()}><div className="flex items-center justify-between border-b border-slate-100 px-5 py-4"><h2 className="font-bold text-ink">{title}</h2><button className="btn btn-muted !p-2" onClick={onClose} aria-label="Close dialog"><X size={17}/></button></div><div className="p-5">{children}</div></div></div> }
function Field({ label, children, required=false }: { label:string;children:React.ReactNode;required?:boolean }) { return <label className="grid gap-1.5 text-xs font-semibold text-slate-600">{label}{required&&<span className="sr-only">required</span>}{children}</label> }
function FormActions({ busy, onCancel }: { busy?:boolean;onCancel:()=>void }) { return <div className="mt-5 flex justify-end gap-2"><button type="button" className="btn btn-muted" onClick={onCancel}>Cancel</button><button className="btn btn-primary" disabled={busy}>{busy?'Saving…':'Save'}</button></div> }

function DashboardPage() {
  const { user, branding, notify }=useApp()
  const [data,setData]=useState<Record<string,any>|null>(null);const [busy,setBusy]=useState(true)
  const load=async()=>{setBusy(true);try{setData(await api.get<Record<string,any>>('/api/dashboard'))}catch(e){notify(errorText(e))}finally{setBusy(false)}}
  useEffect(()=>{void load()},[])
  if(busy&&!data)return <Loading />
  if(user.role==='STUDENT') {
    const summary=data?.summary??{};const invoices=(data?.invoices??[]) as Invoice[]
    return <><PageTitle eyebrow="Student panel" title={`Welcome, ${user.displayName.split(' ')[0]}`} subtitle={`Your stay and payment information at ${branding.hostelName}.`} />
      <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><Metric title="Monthly fee" value={money(summary.monthlyFee)} icon={CircleDollarSign} tone="teal"/><Metric title="Current balance" value={money(summary.balance)} icon={Wallet} tone="gold"/><Metric title="Pending submissions" value={String(summary.pendingPayments??0)} icon={FileCheck2} tone="blue"/><Metric title="Assigned bed" value={data?.student?.room?`${data.student.room} · ${data.student.bedNumber??''}`:'Not assigned'} icon={DoorOpen} tone="slate"/></div>
      <div className="mt-6 grid gap-5 xl:grid-cols-[1.35fr_.65fr]"><Card><CardHead title="My fee records" subtitle="Monthly obligations and verified payments." action={<a href="/fees" className="text-xs font-bold text-teal">View all</a>}/>{invoices.length?<DataTable columns={['Billing month','Due date','Fee','Paid','Balance','Status']} rows={invoices.slice(0,6).map(i=>[dateMonth(i.billingMonth),date(i.dueDate),money(i.feeAmount),money(i.paidAmount),money(i.balance),<Status value={i.status}/>])}/>:<Empty title="No fee records" subtitle="Your monthly fee records will show here."/>}</Card><Card><CardHead title="Your room"/><div className="p-5">{data?.student?.room?<><div className="text-3xl font-bold text-ink">{data.student.room}</div><div className="mt-1 text-sm text-slate-500">Bed {data.student.bedNumber??'—'}</div><div className="mt-6 rounded-xl bg-teal/5 p-4 text-sm leading-6 text-slate-600">For room changes or hostel support, contact the hostel manager.</div></>:<Empty title="No room assigned" subtitle="Ask the hostel manager about your room assignment."/>}</div></Card></div>
      <Card className="mt-5"><CardHead title="Recent updates"/><div className="divide-y divide-slate-100">{(data?.notifications??[]).slice(0,5).map((n:any)=><div key={n.id} className="px-5 py-4"><div className="text-sm font-semibold">{n.title}</div><div className="mt-1 text-xs text-slate-500">{n.message}</div></div>)}</div>{!(data?.notifications??[]).length&&<Empty title="No updates" subtitle="Fee and receipt updates will appear here."/>}</Card>
    </>
  }
  const d=data as unknown as Dashboard|undefined
  const currencyTip=(value:number)=>money(value)
  return <><PageTitle eyebrow={user.role==='OWNER'?'Owner overview':'Manager workspace'} title="Hostel overview" subtitle={`Live operating figures from ${branding.hostelName}.`} action={<button className="btn btn-muted" onClick={()=>void load()}><Activity size={15}/> Refresh</button>}/>
    <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><Metric title="Active students" value={String(d?.activeStudents??0)} icon={Users} tone="teal" foot={`${d?.occupancyPercent??0}% occupancy`}/><Metric title="Available beds" value={`${d?.availableBeds??0} / ${d?.capacity??0}`} icon={DoorOpen} tone="blue" foot={`${d?.occupiedBeds??0} currently occupied`}/><Metric title="Verified collections" value={money(d?.verifiedCollections)} icon={ArrowDownLeft} tone="teal" foot="This month"/><Metric title="Outstanding fees" value={money(d?.outstanding)} icon={Wallet} tone="gold" foot={`${money(d?.overdue)} overdue`}/></div>
    <div className="mt-4 grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><Metric title="Operating expenses" value={money(d?.expenses)} icon={ArrowDownLeft} tone="slate" foot="This month"/><Metric title="Pending payment reviews" value={String(d?.pendingPayments??0)} icon={FileCheck2} tone="gold" foot="Awaiting staff decision"/><Metric title="Owner withdrawals" value={money(d?.withdrawals)} icon={ArrowDownToLine} tone="slate" foot="Recorded separately"/><Metric title="Operating position" value={money(d?.operatingPosition)} icon={CircleDollarSign} tone="blue" foot="Verified collections less expenses"/></div>
    <div className="mt-6 grid gap-5 xl:grid-cols-[1.45fr_.75fr]"><Card><CardHead title="Collections and expenses" subtitle="Actual verified fees and recorded operating costs."/><div className="h-[280px] p-3 pr-6">{d?.monthly?.length?<ResponsiveContainer width="100%" height="100%"><AreaChart data={d.monthly}><defs><linearGradient id="colFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#168b8d" stopOpacity={.2}/><stop offset="95%" stopColor="#168b8d" stopOpacity={0}/></linearGradient><linearGradient id="expFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#d9a646" stopOpacity={.2}/><stop offset="95%" stopColor="#d9a646" stopOpacity={0}/></linearGradient></defs><CartesianGrid stroke="#edf1f1" vertical={false}/><XAxis dataKey="month" tickLine={false} axisLine={false} fontSize={11}/><YAxis tickFormatter={v=>`${Math.round(Number(v)/1000)}k`} tickLine={false} axisLine={false} fontSize={11}/><Tooltip formatter={currencyTip}/><Area type="monotone" dataKey="collections" name="Verified collections" stroke="#168b8d" fill="url(#colFill)" strokeWidth={2.5}/><Area type="monotone" dataKey="expenses" name="Operating expenses" stroke="#d9a646" fill="url(#expFill)" strokeWidth={2.5}/></AreaChart></ResponsiveContainer>:<Empty title="No financial activity yet"/>}</div></Card>
      <Card><CardHead title="Expense categories" subtitle="Recorded expense totals in the last six months."/><div className="h-[220px] px-3">{d?.categories?.some(c=>Number(c.value)>0)?<ResponsiveContainer width="100%" height="100%"><PieChart><Pie data={d.categories.filter(c=>Number(c.value)>0)} dataKey="value" nameKey="name" innerRadius={55} outerRadius={83} paddingAngle={3}>{d.categories.filter(c=>Number(c.value)>0).map((c,i)=><Cell key={c.name} fill={['#168b8d','#d9a646','#31536b','#71b5ac','#83a5b6','#d7895b'][i%6]}/>)}</Pie><Tooltip formatter={currencyTip}/></PieChart></ResponsiveContainer>:<div className="grid h-full place-items-center text-sm text-slate-400">No expenses recorded</div>}</div><div className="grid gap-2 px-5 pb-5">{(d?.categories??[]).filter(c=>Number(c.value)>0).slice(0,4).map(c=><div key={c.name} className="flex justify-between text-xs"><span className="text-slate-500">{c.name}</span><strong>{money(c.value)}</strong></div>)}</div></Card></div>
    <div className="mt-5 grid gap-5 xl:grid-cols-2"><Card><CardHead title={user.role==='OWNER'?'Recent verified payments':'Payment activity'} action={<a href="/payments" className="text-xs font-bold text-teal">Open payments</a>}/>{d?.recentPayments?.length?<DataTable columns={['Student','Month','Amount','Status']} rows={d.recentPayments.map((p:any)=>[p.studentName??p.studentCode??'Student',dateMonth(p.billingMonth),money(p.amount),<Status value={p.status}/>])}/>:<Empty title="No payments submitted"/>}</Card><Card><CardHead title="Bills needing attention" subtitle={`${d?.upcomingBills??0} upcoming or overdue within 14 days.`} action={<a href="/bills" className="text-xs font-bold text-teal">Manage</a>}/>{d?.upcomingBillList?.length?<DataTable columns={['Bill','Due date','Status']} rows={d.upcomingBillList.map((b:any)=>[b.category,date(b.dueDate),<Status value={b.status}/>])}/>:<Empty title="No upcoming bills"/>}</Card></div>
  </>
}

function Metric({ title,value,icon:Icon,tone,foot }: { title:string;value:string;icon:typeof Home;tone:string;foot?:string }) { const tones:Record<string,string>={teal:'bg-teal/10 text-teal',gold:'bg-gold/20 text-amber-700',blue:'bg-blue-50 text-blue-700',slate:'bg-slate-100 text-slate-600'};return <Card className="p-4"><div className="flex items-start justify-between"><div><div className="text-xs font-medium text-slate-500">{title}</div><div className="mt-2 text-xl font-bold tracking-tight text-ink">{value}</div></div><div className={`grid h-9 w-9 place-items-center rounded-xl ${tones[tone]??tones.slate}`}><Icon size={17}/></div></div>{foot&&<div className="mt-3 border-t border-slate-100 pt-2 text-[11px] text-slate-400">{foot}</div>}</Card> }
function DataTable({ columns,rows }: { columns:string[];rows:React.ReactNode[][] }) { return <div className="table-wrap"><table><thead><tr>{columns.map(c=><th key={c}>{c}</th>)}</tr></thead><tbody>{rows.map((r,i)=><tr key={i}>{r.map((cell,j)=><td key={j}>{cell}</td>)}</tr>)}</tbody></table></div> }
function errorText(e:unknown) { return e instanceof Error?e.message:'Something went wrong. Please try again.' }

function StudentsPage() {
  const {user,notify}=useApp();const [rows,setRows]=useState<Student[]>([]);const [rooms,setRooms]=useState<Room[]>([]);const [search,setSearch]=useState('');const [status,setStatus]=useState('');const [busy,setBusy]=useState(true);const [modal,setModal]=useState(false);const [saving,setSaving]=useState(false);const [edit,setEdit]=useState<Student|null>(null);const [transfer,setTransfer]=useState<Student|null>(null)
  const load=async()=>{setBusy(true);try{const params=new URLSearchParams({page:'0',size:'100'});if(search)params.set('search',search);if(status)params.set('status',status);setRows(await api.get<Student[]>(`/api/students?${params}`));if(user.role!=='STUDENT')setRooms(await api.get<Room[]>('/api/rooms?page=0&size=100'))}catch(e){notify(errorText(e))}finally{setBusy(false)}}
  useEffect(()=>{const h=window.setTimeout(()=>void load(),180);return()=>clearTimeout(h)},[search,status])
  const create=async(e:React.FormEvent<HTMLFormElement>)=>{e.preventDefault();const f=new FormData(e.currentTarget);setSaving(true);try{await api.post('/api/students',{studentCode:f.get('studentCode'),fullName:f.get('fullName'),contact:f.get('contact'),email:f.get('email'),initialPassword:f.get('initialPassword'),monthlyFee:Number(f.get('monthlyFee')),dueDay:Number(f.get('dueDay')),registrationDate:f.get('registrationDate'),checkInDate:f.get('checkInDate')||null,roomId:f.get('roomId')?Number(f.get('roomId')):null,bedNumber:f.get('bedNumber')||null,emergencyContact:f.get('emergencyContact')||null,address:f.get('address')||null,notes:f.get('notes')||null});notify('Student registered');setModal(false);await load()}catch(err){notify(errorText(err))}finally{setSaving(false)}}
  const uploadPhoto=async(file:File,id:number)=>{const form=new FormData();form.append('file',file);try{await api.post(`/api/students/${id}/photo`,form);notify('Student photo updated')}catch(e){notify(errorText(e))}}
  const checkout=async(id:number)=>{if(!window.confirm('Check out this student and preserve their fee history?'))return;try{await api.post(`/api/students/${id}/checkout?date=${initialDate()}&reason=Staff%20checkout`);notify('Student checked out');await load()}catch(e){notify(errorText(e))}}
  const update=async(e:React.FormEvent<HTMLFormElement>)=>{e.preventDefault();if(!edit)return;const f=new FormData(e.currentTarget);setSaving(true);try{await api.put(`/api/students/${edit.id}`,{fullName:f.get('fullName'),contact:f.get('contact'),monthlyFee:Number(f.get('monthlyFee')),dueDay:Number(f.get('dueDay')),emergencyContact:f.get('emergencyContact')||null,address:f.get('address')||null,notes:f.get('notes')||null});notify('Student record updated');setEdit(null);await load()}catch(err){notify(errorText(err))}finally{setSaving(false)}}
  return <><PageTitle eyebrow={user.role==='STUDENT'?'My account':'Student records'} title={user.role==='STUDENT'?'My profile':'Students'} subtitle={user.role==='STUDENT'?'Your private hostel profile.':`${rows.length} records in this page. Search by student ID or name.`} action={user.role!=='STUDENT'?<button className="btn btn-primary" onClick={()=>setModal(true)}><Plus size={16}/> Register student</button>:undefined}/>
    <Card><div className="flex flex-wrap items-center justify-between gap-3 border-b border-slate-100 p-4"><div className="relative min-w-[220px] flex-1 sm:max-w-sm"><Search size={15} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400"/><input className="field pl-9" placeholder="Search name or student ID" value={search} onChange={e=>setSearch(e.target.value)}/></div>{user.role!=='STUDENT'&&<select className="field w-auto min-w-36" value={status} onChange={e=>setStatus(e.target.value)}><option value="">All statuses</option><option>ACTIVE</option><option>CHECKED_OUT</option><option>INACTIVE</option></select>}</div>
      {busy?<Loading/>:rows.length?<div className="table-wrap"><table><thead><tr><th>Student</th><th>Contact</th><th>Room / bed</th><th>Monthly fee</th><th>Status</th>{user.role!=='STUDENT'&&<th>Actions</th>}</tr></thead><tbody>{rows.map(s=><tr key={s.id}><td><div className="flex items-center gap-3">{s.photoFileId?<img src={`${api.base}/api/files/${s.photoFileId}`} alt={`${s.fullName} photo`} className="h-9 w-9 rounded-full object-cover"/>:<div className="grid h-9 w-9 place-items-center rounded-full bg-teal/10 text-xs font-bold text-teal">{s.fullName.slice(0,1)}</div>}<div><div className="font-semibold">{s.fullName}</div><div className="mt-1 text-[11px] text-slate-400">{s.studentCode} · Registered {date(s.checkInDate)}</div></div></div></td><td>{s.contact}<div className="mt-1 text-[11px] text-slate-400">{s.email}</div></td><td>{s.room?`${s.room} · ${s.bedNumber}`:'—'}</td><td>{money(s.monthlyFee)}</td><td><Status value={s.status}/></td>{user.role!=='STUDENT'&&<td><div className="flex flex-wrap gap-2"><button className="btn btn-muted !px-2 !py-1.5" onClick={()=>setEdit(s)}>Edit</button>{s.status==='ACTIVE'&&<button className="btn btn-muted !px-2 !py-1.5" onClick={()=>setTransfer(s)}>Change room</button>}<label className="btn btn-muted !px-2 !py-1.5">Photo<input className="sr-only" type="file" accept="image/png,image/jpeg,image/webp" onChange={e=>e.target.files?.[0]&&uploadPhoto(e.target.files[0],s.id)}/></label>{s.status==='ACTIVE'&&<button className="btn btn-muted !px-2 !py-1.5" onClick={()=>void checkout(s.id)}>Check out</button>}</div></td>}</tr>)}</tbody></table></div>:<Empty title="No students found" subtitle="Try a different search or register a student."/>}</Card>
    {modal&&<Modal title="Register student" onClose={()=>setModal(false)} wide><form onSubmit={create}><div className="grid gap-4 sm:grid-cols-2"><Field label="Student ID" required><input className="field" name="studentCode" required maxLength={40}/></Field><Field label="Full name" required><input className="field" name="fullName" required maxLength={160}/></Field><Field label="Contact number" required><input className="field" name="contact" required maxLength={40}/></Field><Field label="Student login email" required><input className="field" name="email" type="email" required/></Field><Field label="Temporary password (12+ characters)" required><input className="field" name="initialPassword" type="password" minLength={12} required/></Field><Field label="Monthly hostel fee (PKR)" required><input className="field" name="monthlyFee" type="number" min="0" step="0.01" required/></Field><Field label="Due day (1–28)" required><input className="field" name="dueDay" type="number" min="1" max="28" defaultValue="5" required/></Field><Field label="Registration date" required><input className="field" name="registrationDate" type="date" defaultValue={initialDate()} required/></Field><Field label="Check-in date"><input className="field" name="checkInDate" type="date" defaultValue={initialDate()}/></Field><Field label="Room"><select className="field" name="roomId"><option value="">Assign later</option>{rooms.filter(r=>r.available>0).map(r=><option key={r.id} value={r.id}>{r.roomNumber} · {r.available} bed(s) free</option>)}</select></Field><Field label="Bed number"><input className="field" name="bedNumber" inputMode="numeric" placeholder="1"/></Field><Field label="Emergency contact"><input className="field" name="emergencyContact" maxLength={160}/></Field><Field label="Address"><input className="field" name="address" maxLength={500}/></Field><Field label="Administrative notes"><input className="field" name="notes" maxLength={1000}/></Field></div><div className="mt-4 rounded-lg bg-amber-50 p-3 text-xs text-amber-800">Share the temporary login password directly with the student. It is stored only as a password hash.</div><FormActions busy={saving} onCancel={()=>setModal(false)}/></form></Modal>}
    {edit&&<Modal title={`Edit ${edit.fullName}`} onClose={()=>setEdit(null)} wide><form onSubmit={update}><div className="grid gap-4 sm:grid-cols-2"><Field label="Full name" required><input className="field" name="fullName" defaultValue={edit.fullName} required/></Field><Field label="Contact number" required><input className="field" name="contact" defaultValue={edit.contact} required/></Field><Field label="Monthly fee (PKR)" required><input className="field" name="monthlyFee" type="number" min="0" step="0.01" defaultValue={edit.monthlyFee} required/></Field><Field label="Due day (1–28)" required><input className="field" name="dueDay" type="number" min="1" max="28" defaultValue={edit.dueDay} required/></Field><Field label="Emergency contact"><input className="field" name="emergencyContact" defaultValue={(edit as any).emergencyContact}/></Field><Field label="Address"><input className="field" name="address" defaultValue={(edit as any).address}/></Field><Field label="Administrative notes"><input className="field" name="notes" defaultValue={(edit as any).notes}/></Field></div><FormActions busy={saving} onCancel={()=>setEdit(null)}/></form></Modal>}
    {transfer&&<AssignmentModal student={transfer} rooms={rooms} onClose={()=>setTransfer(null)} onSaved={()=>{setTransfer(null);void load()}}/>}
  </>
}

function AssignmentModal({student,rooms,onClose,onSaved}:{student:Student;rooms:Room[];onClose:()=>void;onSaved:()=>void}) { const {notify}=useApp();const [saving,setSaving]=useState(false);const save=async(e:React.FormEvent<HTMLFormElement>)=>{e.preventDefault();const f=new FormData(e.currentTarget);setSaving(true);try{await api.post(`/api/students/${student.id}/assign`,{roomId:Number(f.get('roomId')),bedNumber:f.get('bedNumber'),date:f.get('date')});notify('Room assignment updated');onSaved()}catch(err){notify(errorText(err))}finally{setSaving(false)}};return <Modal title={`Change room for ${student.fullName}`} onClose={onClose}><form onSubmit={save} className="grid gap-4"><Field label="Room with available capacity" required><select className="field" name="roomId" required>{rooms.filter(r=>r.status==='ACTIVE'&&r.available>0).map(r=><option key={r.id} value={r.id}>{r.roomNumber} · {r.available} bed(s) free</option>)}</select></Field><Field label="Bed number" required><input className="field" name="bedNumber" inputMode="numeric" required/></Field><Field label="Assignment start date" required><input className="field" name="date" type="date" defaultValue={initialDate()} required/></Field><FormActions busy={saving} onCancel={onClose}/></form></Modal> }

function RoomsPage() {
  const {user,notify}=useApp();const [rows,setRows]=useState<Room[]>([]);const [busy,setBusy]=useState(true);const [modal,setModal]=useState(false);const [saving,setSaving]=useState(false);const [edit,setEdit]=useState<Room|null>(null)
  const load=async()=>{setBusy(true);try{setRows(await api.get<Room[]>('/api/rooms?page=0&size=100'))}catch(e){notify(errorText(e))}finally{setBusy(false)}}
  useEffect(()=>{void load()},[])
  const save=async(e:React.FormEvent<HTMLFormElement>)=>{e.preventDefault();const f=new FormData(e.currentTarget);const body={roomNumber:f.get('roomNumber'),section:f.get('section')||null,capacity:Number(f.get('capacity')),notes:f.get('notes')||null};setSaving(true);try{if(edit)await api.put(`/api/rooms/${edit.id}`,body);else await api.post('/api/rooms',body);notify(edit?'Room updated':'Room added');setModal(false);setEdit(null);await load()}catch(err){notify(errorText(err))}finally{setSaving(false)}}
  const deactivate=async(r:Room)=>{if(!window.confirm(`Deactivate room ${r.roomNumber}?`))return;try{await api.del(`/api/rooms/${r.id}`);notify('Room deactivated');await load()}catch(e){notify(errorText(e))}}
  return <><PageTitle eyebrow="Accommodation" title="Rooms & beds" subtitle="Occupancy is calculated from active student assignments." action={user.role!=='STUDENT'?<button className="btn btn-primary" onClick={()=>{setEdit(null);setModal(true)}}><Plus size={16}/> Add room</button>:undefined}/><div className="mb-5 grid gap-4 sm:grid-cols-3"><Metric title="Room capacity" value={String(rows.reduce((n,r)=>n+Number(r.capacity),0))} icon={Building2} tone="blue"/><Metric title="Occupied beds" value={String(rows.reduce((n,r)=>n+Number(r.occupied),0))} icon={Users} tone="teal"/><Metric title="Available beds" value={String(rows.reduce((n,r)=>n+Number(r.available),0))} icon={DoorOpen} tone="gold"/></div><Card>{busy?<Loading/>:rows.length?<DataTable columns={['Room','Section','Capacity','Occupied','Available','Status','Actions']} rows={rows.map(r=>[<strong>{r.roomNumber}</strong>,r.section||'—',r.capacity,r.occupied,r.available,<Status value={r.status}/>,r.status==='ACTIVE'?<div className="flex gap-2"><button className="btn btn-muted !px-2 !py-1" onClick={()=>{setEdit(r);setModal(true)}}>Edit</button><button className="btn btn-muted !px-2 !py-1" onClick={()=>void deactivate(r)}>Deactivate</button></div>:'—'])}/>:<Empty title="No rooms added" subtitle="Add rooms to track hostel capacity and assignments."/>}</Card>
    {modal&&<Modal title={edit?'Edit room':'Add room'} onClose={()=>{setModal(false);setEdit(null)}}><form onSubmit={save} className="grid gap-4"><Field label="Room number" required><input className="field" name="roomNumber" defaultValue={edit?.roomNumber} required/></Field><Field label="Floor / section"><input className="field" name="section" defaultValue={edit?.section}/></Field><Field label="Bed capacity" required><input className="field" name="capacity" type="number" min="1" max="200" defaultValue={edit?.capacity??4} required/></Field><Field label="Notes"><textarea className="field" name="notes" rows={3} defaultValue={edit?.notes}/></Field><FormActions busy={saving} onCancel={()=>{setModal(false);setEdit(null)}}/></form></Modal>}
  </>
}

function FeesPage() {
  const {user,notify}=useApp();const [rows,setRows]=useState<Invoice[]>([]);const [busy,setBusy]=useState(true);const [making,setMaking]=useState(false);const [pay,setPay]=useState<Invoice|null>(null)
  const load=async()=>{setBusy(true);try{setRows(await api.get<Invoice[]>('/api/invoices?page=0&size=100'))}catch(e){notify(errorText(e))}finally{setBusy(false)}}
  useEffect(()=>{void load()},[])
  const generate=async()=>{setMaking(true);try{const r=await api.post<{created:number}>(`/api/invoices/generate?month=${new Date().toISOString().slice(0,7)}`);notify(`${r.created} monthly invoice(s) created`);await load()}catch(e){notify(errorText(e))}finally{setMaking(false)}}
  return <><PageTitle eyebrow={user.role==='STUDENT'?'Student panel':'Accounts'} title={user.role==='STUDENT'?'My hostel fees':'Fee records'} subtitle={user.role==='STUDENT'?'View your own monthly fee obligations, balances, and due dates.':'Historical charges remain unchanged when a student’s current monthly fee changes.'} action={user.role!=='STUDENT'?<button className="btn btn-primary" disabled={making} onClick={()=>void generate()}><Zap size={15}/>{making?'Generating…':'Generate this month'}</button>:undefined}/>
    <Card>{busy?<Loading/>:rows.length?<DataTable columns={user.role==='STUDENT'?['Billing month','Due date','Fee','Verified paid','Balance','Status','Action']:['Student','Room','Billing month','Due date','Fee','Verified paid','Balance','Status']} rows={rows.map((i:any)=>user.role==='STUDENT'?[dateMonth(i.billingMonth),date(i.dueDate),money(i.feeAmount),money(i.paidAmount),money(i.balance),<Status value={i.status}/>,Number(i.balance)>0?<button className="btn btn-primary !px-2 !py-1.5" onClick={()=>setPay(i)}>Submit payment</button>:'—']:[<><strong>{i.studentName}</strong><div className="mt-1 text-[11px] text-slate-400">{i.studentCode}</div></>,i.room||'—',dateMonth(i.billingMonth),date(i.dueDate),money(i.feeAmount),money(i.paidAmount),money(i.balance),<Status value={i.status}/>])}/>:<Empty title="No fee invoices" subtitle={user.role==='STUDENT'?'Your fee invoices have not been generated yet.':'Generate the monthly fee obligations for active students.'}/>}</Card>
    {pay&&<PaymentSubmissionModal invoice={pay} onClose={()=>setPay(null)} onSaved={()=>{setPay(null);void load()}}/>}
  </>
}

function PaymentSubmissionModal({invoice,onClose,onSaved}:{invoice:Invoice;onClose:()=>void;onSaved:()=>void}) {
  const {notify}=useApp();const [saving,setSaving]=useState(false)
  const submit=async(e:React.FormEvent<HTMLFormElement>)=>{e.preventDefault();const f=new FormData(e.currentTarget);setSaving(true);try{let proofFileId:number|undefined;const proof=f.get('proof') as File;if(proof?.size){const upload=new FormData();upload.append('file',proof);const out=await api.post<{id:number}>('/api/files',upload);proofFileId=out.id}await api.post('/api/payments',{invoiceId:invoice.id,amount:Number(f.get('amount')),paymentDate:f.get('paymentDate'),method:f.get('method'),reference:f.get('reference')||null,proofFileId,idempotencyKey:crypto.randomUUID()});notify('Payment submitted for verification');onSaved()}catch(err){notify(errorText(err))}finally{setSaving(false)}}
  return <Modal title="Submit a payment" onClose={onClose}><form onSubmit={submit} className="grid gap-4"><div className="rounded-xl bg-teal/5 p-4 text-sm"><div className="font-semibold">{dateMonth(invoice.billingMonth)} fee</div><div className="mt-1 text-slate-500">Remaining balance: <strong className="text-ink">{money(invoice.balance)}</strong></div></div><Field label="Amount paid (PKR)" required><input className="field" name="amount" type="number" min="0.01" max={invoice.balance} step="0.01" required/></Field><Field label="Payment date" required><input className="field" type="date" name="paymentDate" defaultValue={initialDate()} required/></Field><Field label="Payment method"><select className="field" name="method"><option value="">Select method</option><option>Cash</option><option>Bank transfer</option><option>Mobile wallet</option><option>Other</option></select></Field><Field label="Transaction / reference number"><input className="field" name="reference" maxLength={120}/></Field><Field label="Payment proof (image or PDF)"><input className="field" type="file" name="proof" accept="image/png,image/jpeg,image/webp,application/pdf"/></Field><p className="text-xs leading-5 text-slate-400">This submission stays pending until a Manager verifies it. It is not counted as a collection yet.</p><FormActions busy={saving} onCancel={onClose}/></form></Modal>
}

function PaymentsPage() {
  const {user,notify}=useApp();const [rows,setRows]=useState<Payment[]>([]);const [busy,setBusy]=useState(true);const [filter,setFilter]=useState(user.role==='STUDENT'?'':'PENDING');const [reject,setReject]=useState<Payment|null>(null);const [reason,setReason]=useState('');const [saving,setSaving]=useState(false)
  const load=async()=>{setBusy(true);try{const q=new URLSearchParams({page:'0',size:'100'});if(filter)q.set('status',filter);setRows(await api.get<Payment[]>(`/api/payments?${q}`))}catch(e){notify(errorText(e))}finally{setBusy(false)}}
  useEffect(()=>{void load()},[filter])
  const decide=async(id:number,action:'approve'|'reject',why?:string)=>{setSaving(true);try{if(action==='approve')await api.post(`/api/payments/${id}/approve`);else await api.post(`/api/payments/${id}/reject`,{reason:why});notify(action==='approve'?'Payment approved; receipt issued':'Payment rejected');setReject(null);setReason('');await load()}catch(e){notify(errorText(e))}finally{setSaving(false)}}
  const reverse=async(id:number)=>{const why=window.prompt('Reason for reversing this approved payment?');if(!why?.trim())return;try{await api.post(`/api/payments/${id}/reverse`,{reason:why});notify('Payment reversed and recorded in the audit log');await load()}catch(e){notify(errorText(e))}}
  const cols=user.role==='STUDENT'?['Billing month','Date submitted','Amount','Method','Status','Receipt']:['Student','Billing month','Payment date','Amount','Method / reference','Proof','Status','Review']
  return <><PageTitle eyebrow={user.role==='STUDENT'?'Student panel':'Financial operations'} title={user.role==='STUDENT'?'Payment history':'Payment review'} subtitle={user.role==='STUDENT'?'Submissions are private to your account. Receipts appear after approval.':'Only approved payments count as verified collections.'} action={<div className="flex gap-2">{user.role!=='STUDENT'&&<select className="field w-auto" value={filter} onChange={e=>setFilter(e.target.value)}><option value="">All statuses</option><option value="PENDING">Pending</option><option value="APPROVED">Approved</option><option value="REJECTED">Rejected</option><option value="REVERSED">Reversed</option></select>}<button className="btn btn-muted" onClick={()=>void load()}><Activity size={15}/> Refresh</button></div>}/>
    <Card>{busy?<Loading/>:rows.length?<div className="table-wrap"><table><thead><tr>{cols.map(c=><th key={c}>{c}</th>)}</tr></thead><tbody>{rows.map(p=><tr key={p.id}>{user.role==='STUDENT'?<><td>{dateMonth(p.billingMonth)}</td><td>{date(p.paymentDate)}</td><td>{money(p.amount)}</td><td>{p.method||'—'}</td><td><Status value={p.status}/>{p.rejectionReason&&<div className="mt-1 max-w-44 text-[11px] text-red-600">{p.rejectionReason}</div>}</td><td>{p.receiptNumber?<button className="btn btn-muted !px-2 !py-1" onClick={()=>download(`/api/receipts/${p.id}.pdf`,`${p.receiptNumber}.pdf`).catch(e=>notify(errorText(e)))}><ArrowDownToLine size={14}/> PDF</button>:'—'}</td></>:<><td><strong>{p.studentName}</strong><div className="mt-1 text-[11px] text-slate-400">{p.studentCode}</div></td><td>{dateMonth(p.billingMonth)}</td><td>{date(p.paymentDate)}</td><td>{money(p.amount)}</td><td>{p.method||'—'}{p.reference&&<div className="mt-1 text-[11px] text-slate-400">{p.reference}</div>}</td><td>{p.proofFileId?<button className="text-xs font-semibold text-teal" onClick={()=>download(`/api/files/${p.proofFileId}`,`payment-proof-${p.id}`).catch(e=>notify(errorText(e)))}>View proof</button>:'—'}</td><td><Status value={p.status}/>{p.rejectionReason&&<div className="mt-1 max-w-44 text-[11px] text-red-600">{p.rejectionReason}</div>}</td><td>{p.status==='PENDING'?<div className="flex gap-1"><button className="btn btn-primary !px-2 !py-1" onClick={()=>void decide(p.id,'approve')}>Approve</button><button className="btn btn-muted !px-2 !py-1" onClick={()=>setReject(p)}>Reject</button></div>:p.status==='APPROVED'&&user.role==='OWNER'?<button className="btn btn-muted !px-2 !py-1" onClick={()=>void reverse(p.id)}>Reverse</button>:p.receiptNumber?<button className="btn btn-muted !px-2 !py-1" onClick={()=>download(`/api/receipts/${p.id}.pdf`,`${p.receiptNumber}.pdf`).catch(e=>notify(errorText(e)))}>Receipt</button>:'—'}</td></>}</tr>)}</tbody></table></div>:<Empty title="No payment records" subtitle={user.role==='STUDENT'?'Your submissions will appear here.':'No submissions match this filter.'}/>}</Card>
    {reject&&<Modal title="Reject payment submission" onClose={()=>{setReject(null);setReason('')}}><div className="mb-3 text-sm text-slate-500">Payment from <strong className="text-ink">{reject.studentName}</strong> for {money(reject.amount)}.</div><label className="grid gap-2 text-sm font-semibold">Reason for rejection<textarea className="field" rows={4} value={reason} onChange={e=>setReason(e.target.value)} required placeholder="Explain what needs to be corrected"/></label><div className="mt-5 flex justify-end gap-2"><button className="btn btn-muted" onClick={()=>setReject(null)}>Cancel</button><button className="btn btn-primary" disabled={!reason.trim()||saving} onClick={()=>void decide(reject.id,'reject',reason)}>{saving?'Saving…':'Reject payment'}</button></div></Modal>}
  </>
}

function ExpensesPage() {
  const {notify}=useApp();const [rows,setRows]=useState<Expense[]>([]);const [categories,setCategories]=useState<{id:number;name:string}[]>([]);const [busy,setBusy]=useState(true);const [modal,setModal]=useState(false);const [saving,setSaving]=useState(false);const [from,setFrom]=useState('');const [to,setTo]=useState('')
  const load=async()=>{setBusy(true);try{const q=new URLSearchParams({page:'0',size:'100'});if(from)q.set('from',from);if(to)q.set('to',to);const [r,c]=await Promise.all([api.get<Expense[]>(`/api/expenses?${q}`),api.get<{id:number;name:string}[]>('/api/expense-categories')]);setRows(r);setCategories(c)}catch(e){notify(errorText(e))}finally{setBusy(false)}}
  useEffect(()=>{void load()},[from,to])
  const save=async(e:React.FormEvent<HTMLFormElement>)=>{e.preventDefault();const f=new FormData(e.currentTarget);setSaving(true);try{let billFileId:number|null=null;const proof=f.get('billFile') as File;if(proof?.size){const upload=new FormData();upload.append('file',proof);billFileId=(await api.post<{id:number}>('/api/files',upload)).id}await api.post('/api/expenses',{categoryId:Number(f.get('categoryId')),amount:Number(f.get('amount')),expenseDate:f.get('expenseDate'),description:f.get('description'),vendor:f.get('vendor')||null,paymentMethod:f.get('paymentMethod')||null,billFileId,idempotencyKey:crypto.randomUUID()});notify('Expense recorded');setModal(false);await load()}catch(err){notify(errorText(err))}finally{setSaving(false)}}
  const reverse=async(id:number)=>{const reason=window.prompt('Reason for reversing this expense?');if(!reason?.trim())return;try{await api.post(`/api/expenses/${id}/reverse`,{reason});notify('Expense reversal recorded');await load()}catch(e){notify(errorText(e))}}
  return <><PageTitle eyebrow="Financial operations" title="Operating expenses" subtitle="Expenses remain separate from owner withdrawals. Corrections are reversed with a reason and audit history." action={<button className="btn btn-primary" onClick={()=>setModal(true)}><Plus size={16}/> Record expense</button>}/>
    <div className="mb-5 grid gap-4 sm:grid-cols-2"><Metric title="Visible expense total" value={money(rows.filter(e=>!e.reversedAt).reduce((n,e)=>n+Number(e.amount),0))} icon={CircleDollarSign} tone="gold" foot="Current filtered dates"/><Metric title="Expense entries" value={String(rows.length)} icon={ClipboardList} tone="blue" foot="Includes reversed history"/></div>
    <Card><div className="flex flex-wrap items-center gap-3 border-b border-slate-100 p-4"><label className="text-xs text-slate-500">From <input className="field ml-2 inline-block w-auto" type="date" value={from} onChange={e=>setFrom(e.target.value)}/></label><label className="text-xs text-slate-500">To <input className="field ml-2 inline-block w-auto" type="date" value={to} onChange={e=>setTo(e.target.value)}/></label></div>{busy?<Loading/>:rows.length?<DataTable columns={['Date','Category','Description','Vendor','Amount','Status','Action']} rows={rows.map(e=>[date(e.expenseDate),e.category,e.description,e.vendor||'—',money(e.amount),e.reversedAt?<Status value="REVERSED"/>:<Status value="RECORDED"/>,!e.reversedAt?<button className="btn btn-muted !px-2 !py-1" onClick={()=>void reverse(e.id)}>Reverse</button>:'—'])}/>:<Empty title="No expenses found" subtitle="Record a bill or operating expense to begin the ledger."/>}</Card>
    {modal&&<Modal title="Record operating expense" onClose={()=>setModal(false)}><form onSubmit={save} className="grid gap-4"><Field label="Category" required><select className="field" name="categoryId" required>{categories.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select></Field><Field label="Amount (PKR)" required><input className="field" name="amount" type="number" min="0.01" step="0.01" required/></Field><Field label="Expense date" required><input className="field" name="expenseDate" type="date" defaultValue={initialDate()} required/></Field><Field label="Description" required><input className="field" name="description" maxLength={500} required/></Field><Field label="Vendor / recipient"><input className="field" name="vendor" maxLength={160}/></Field><Field label="Payment method"><select className="field" name="paymentMethod"><option value="">Not recorded</option><option>Cash</option><option>Bank transfer</option><option>Mobile wallet</option><option>Other</option></select></Field><Field label="Bill or receipt evidence"><input className="field" name="billFile" type="file" accept="image/png,image/jpeg,image/webp,application/pdf"/></Field><FormActions busy={saving} onCancel={()=>setModal(false)}/></form></Modal>}
  </>
}

function BillsPage() {
  const {notify}=useApp();const [rows,setRows]=useState<Bill[]>([]);const [busy,setBusy]=useState(true);const [modal,setModal]=useState<'schedule'|'pay'|null>(null);const [active,setActive]=useState<Bill|null>(null);const [saving,setSaving]=useState(false)
  const load=async()=>{setBusy(true);try{setRows(await api.get<Bill[]>('/api/bills?page=0&size=100'))}catch(e){notify(errorText(e))}finally{setBusy(false)}}
  useEffect(()=>{void load()},[])
  const submit=async(e:React.FormEvent<HTMLFormElement>)=>{e.preventDefault();const f=new FormData(e.currentTarget);setSaving(true);try{if(modal==='schedule')await api.post('/api/bills/schedules',{category:f.get('category'),vendor:f.get('vendor')||null,expectedAmount:Number(f.get('amount')),frequency:f.get('frequency'),nextDueDate:f.get('dueDate'),notes:f.get('notes')||null,idempotencyKey:crypto.randomUUID()});else if(active){let billFileId:number|null=null;const file=f.get('billFile') as File;if(file?.size){const upload=new FormData();upload.append('file',file);billFileId=(await api.post<{id:number}>('/api/files',upload)).id}await api.post(`/api/bills/${active.id}/payment`,{category:active.category,vendor:f.get('vendor')||null,amount:Number(f.get('amount')),dueDate:active.dueDate,paymentDate:f.get('paymentDate')||null,billFileId,notes:f.get('notes')||null})}notify(modal==='schedule'?'Recurring bill saved':'Bill updated');setModal(null);setActive(null);await load()}catch(err){notify(errorText(err))}finally{setSaving(false)}}
  return <><PageTitle eyebrow="Utilities & rent" title="Recurring bills" subtitle="Schedules and due records are persisted. Upcoming bills are surfaced in the staff dashboard." action={<button className="btn btn-primary" onClick={()=>setModal('schedule')}><Plus size={16}/> Add bill schedule</button>}/>
    <Card>{busy?<Loading/>:rows.length?<DataTable columns={['Category','Due date','Expected / actual','Status','Action']} rows={rows.map(b=>[<><strong>{b.category}</strong><div className="mt-1 text-[11px] text-slate-400">{b.vendor}</div></>,date(b.dueDate),money(b.amount??b.expectedAmount),<Status value={b.status}/>,b.status!=='PAID'?<button className="btn btn-muted !px-2 !py-1" onClick={()=>{setActive(b);setModal('pay')}}>Update payment</button>:'—'])}/>:<Empty title="No bills on file" subtitle="Add recurring schedules for utilities, rent, or other services."/>}</Card>
    {modal==='schedule'&&<Modal title="Add recurring bill" onClose={()=>setModal(null)}><form onSubmit={submit} className="grid gap-4"><Field label="Bill category" required><select className="field" name="category" required><option>Electricity</option><option>Gas</option><option>Water</option><option>Wi-Fi / Internet</option><option>Rent</option><option>Other recurring bill</option></select></Field><Field label="Vendor / service provider"><input className="field" name="vendor"/></Field><Field label="Expected amount (PKR)" required><input className="field" name="amount" type="number" min="0" step="0.01" defaultValue="0" required/></Field><Field label="Billing frequency" required><select className="field" name="frequency"><option value="MONTHLY">Monthly</option><option value="QUARTERLY">Quarterly</option><option value="YEARLY">Yearly</option></select></Field><Field label="Next due date" required><input className="field" name="dueDate" type="date" defaultValue={initialDate()} required/></Field><Field label="Notes"><textarea className="field" name="notes" rows={2}/></Field><FormActions busy={saving} onCancel={()=>setModal(null)}/></form></Modal>}
    {modal==='pay'&&active&&<Modal title={`Update ${active.category} bill`} onClose={()=>{setModal(null);setActive(null)}}><form onSubmit={submit} className="grid gap-4"><div className="text-sm text-slate-500">Due {date(active.dueDate)} · expected {money(active.amount??active.expectedAmount)}</div><Field label="Actual amount (PKR)" required><input className="field" name="amount" type="number" min="0" step="0.01" defaultValue={active.amount??active.expectedAmount??0} required/></Field><Field label="Payment date"><input className="field" name="paymentDate" type="date"/></Field><Field label="Vendor / recipient"><input className="field" name="vendor" defaultValue={active.vendor}/></Field><Field label="Bill receipt / proof"><input className="field" name="billFile" type="file" accept="image/png,image/jpeg,image/webp,application/pdf"/></Field><Field label="Notes"><textarea className="field" name="notes" rows={2}/></Field><div className="text-xs text-slate-400">Leave the payment date empty to keep the bill unpaid.</div><FormActions busy={saving} onCancel={()=>{setModal(null);setActive(null)}}/></form></Modal>}
  </>
}

function StaffPage() {
  const {notify}=useApp();const [employees,setEmployees]=useState<Employee[]>([]);const [salaries,setSalaries]=useState<any[]>([]);const [advances,setAdvances]=useState<any[]>([]);const [busy,setBusy]=useState(true);const [modal,setModal]=useState<'employee'|'salary'|'advance'|'repay'|null>(null);const [active,setActive]=useState<any>(null);const [saving,setSaving]=useState(false)
  const load=async()=>{setBusy(true);try{const [e,s,a]=await Promise.all([api.get<Employee[]>('/api/employees'),api.get<any[]>('/api/salaries?page=0&size=100'),api.get<any[]>('/api/advances')]);setEmployees(e);setSalaries(s);setAdvances(a)}catch(err){notify(errorText(err))}finally{setBusy(false)}}
  useEffect(()=>{void load()},[])
  const submit=async(e:React.FormEvent<HTMLFormElement>)=>{e.preventDefault();const f=new FormData(e.currentTarget);setSaving(true);try{if(modal==='employee')await api.post('/api/employees',{employeeCode:f.get('employeeCode'),fullName:f.get('fullName'),title:f.get('title'),contact:f.get('contact')||null,joiningDate:f.get('joiningDate'),salaryAmount:Number(f.get('salaryAmount')),notes:f.get('notes')||null});else if(modal==='salary')await api.post('/api/salaries',{employeeId:Number(f.get('employeeId')),salaryPeriod:`${f.get('salaryPeriod')}-01`,amountDue:Number(f.get('amountDue')),amountPaid:Number(f.get('amountPaid')||0),paymentDate:f.get('paymentDate')||null,notes:f.get('notes')||null,idempotencyKey:crypto.randomUUID()});else if(modal==='advance')await api.post('/api/advances',{employeeId:Number(f.get('employeeId')),amount:Number(f.get('amount')),issuedDate:f.get('date'),reason:f.get('reason'),idempotencyKey:crypto.randomUUID()});else if(modal==='repay'&&active)await api.post(`/api/advances/${active.id}/repayments`,{amount:Number(f.get('amount')),transactionDate:f.get('date'),note:f.get('note')||null,idempotencyKey:crypto.randomUUID()});notify('Staff record saved');setModal(null);setActive(null);await load()}catch(err){notify(errorText(err))}finally{setSaving(false)}}
  const deactivate=async(e:Employee)=>{if(!window.confirm(`Deactivate ${e.fullName}? Historical salary and advance records remain.`))return;try{await api.del(`/api/employees/${e.id}`);notify('Employee deactivated');await load()}catch(err){notify(errorText(err))}}
  return <><PageTitle eyebrow="Hostel staff" title="Employees & payroll" subtitle="Salary obligations and payments are tracked separately from employee advances." action={<button className="btn btn-primary" onClick={()=>setModal('employee')}><Plus size={16}/> Add employee</button>}/>
    {busy?<Loading/>:<><div className="grid gap-4 sm:grid-cols-3"><Metric title="Active employees" value={String(employees.filter(e=>e.status==='ACTIVE').length)} icon={Users} tone="teal"/><Metric title="Salary outstanding" value={money(salaries.reduce((n,s)=>n+Number(s.outstanding),0))} icon={Wallet} tone="gold"/><Metric title="Advances outstanding" value={money(advances.reduce((n,a)=>n+Number(a.outstanding),0))} icon={ArrowDownLeft} tone="blue"/></div>
      <Card className="mt-5"><CardHead title="Employee records" action={<button className="btn btn-muted !px-2 !py-1" onClick={()=>setModal('salary')}><Plus size={14}/> Salary obligation</button>}/>{employees.length?<DataTable columns={['Employee','Role','Joined','Salary arrangement','Status','Action']} rows={employees.map(e=>[<><strong>{e.fullName}</strong><div className="mt-1 text-[11px] text-slate-400">{e.employeeCode} · {e.contact}</div></>,e.title,date(e.joiningDate),money(e.salaryAmount),<Status value={e.status}/>,e.status==='ACTIVE'?<button className="btn btn-muted !px-2 !py-1" onClick={()=>void deactivate(e)}>Deactivate</button>:'—'])}/>:<Empty title="No employees on file" subtitle="Add hostel staff to record salary obligations and advances."/>}</Card>
      <div className="mt-5 grid gap-5 xl:grid-cols-2"><Card><CardHead title="Salary obligations" subtitle="Partial salary payments are included in the paid amount." action={<button className="btn btn-muted !px-2 !py-1" onClick={()=>setModal('salary')}><Plus size={14}/> Record payment</button>}/>{salaries.length?<DataTable columns={['Employee','Period','Amount due','Paid','Outstanding']} rows={salaries.map(s=>[s.employeeName,dateMonth(s.salaryPeriod),money(s.amountDue),money(s.amountPaid),money(s.outstanding)])}/>:<Empty title="No salary entries"/>}</Card>
        <Card><CardHead title="Employee advances" action={<button className="btn btn-muted !px-2 !py-1" onClick={()=>setModal('advance')}><Plus size={14}/> Issue advance</button>}/>{advances.length?<DataTable columns={['Employee','Issued','Amount','Outstanding','Action']} rows={advances.map(a=>[a.employeeName,date(a.issuedDate),money(a.amount),money(a.outstanding),Number(a.outstanding)>0?<button className="btn btn-muted !px-2 !py-1" onClick={()=>{setActive(a);setModal('repay')}}>Record repayment</button>:'Settled'])}/>:<Empty title="No advances recorded"/>}</Card></div>
    </>}
    {modal&&<Modal title={modal==='employee'?'Add employee':modal==='salary'?'Record salary obligation / payment':modal==='advance'?'Issue employee advance':'Record advance repayment'} onClose={()=>{setModal(null);setActive(null)}}><form onSubmit={submit} className="grid gap-4">{modal==='employee'?<><Field label="Employee ID" required><input className="field" name="employeeCode" required/></Field><Field label="Full name" required><input className="field" name="fullName" required/></Field><Field label="Job title" required><input className="field" name="title" required/></Field><Field label="Contact"><input className="field" name="contact"/></Field><Field label="Joining date" required><input className="field" name="joiningDate" type="date" defaultValue={initialDate()} required/></Field><Field label="Monthly salary arrangement (PKR)" required><input className="field" name="salaryAmount" type="number" min="0" step="0.01" defaultValue="0" required/></Field><Field label="Notes"><input className="field" name="notes"/></Field></>:modal==='salary'?<><Field label="Employee" required><select className="field" name="employeeId" required>{employees.filter(e=>e.status==='ACTIVE').map(e=><option key={e.id} value={e.id}>{e.fullName} · {e.employeeCode}</option>)}</select></Field><Field label="Salary period" required><input className="field" name="salaryPeriod" type="month" defaultValue={new Date().toISOString().slice(0,7)} required/></Field><Field label="Amount due (PKR)" required><input className="field" name="amountDue" type="number" min="0" step="0.01" required/></Field><Field label="Payment now (PKR)"><input className="field" name="amountPaid" type="number" min="0" step="0.01" defaultValue="0"/></Field><Field label="Payment date"><input className="field" name="paymentDate" type="date" defaultValue={initialDate()}/></Field><Field label="Notes"><input className="field" name="notes"/></Field></>:modal==='advance'?<><Field label="Employee" required><select className="field" name="employeeId" required>{employees.filter(e=>e.status==='ACTIVE').map(e=><option key={e.id} value={e.id}>{e.fullName} · {e.employeeCode}</option>)}</select></Field><Field label="Advance amount (PKR)" required><input className="field" name="amount" type="number" min="0.01" step="0.01" required/></Field><Field label="Issued date" required><input className="field" name="date" type="date" defaultValue={initialDate()} required/></Field><Field label="Reason" required><textarea className="field" name="reason" required/></Field></>:<><div className="rounded-lg bg-amber-50 p-3 text-sm">Outstanding advance: <strong>{money(active?.outstanding)}</strong></div><Field label="Repayment amount (PKR)" required><input className="field" name="amount" type="number" min="0.01" max={active?.outstanding} step="0.01" required/></Field><Field label="Repayment date" required><input className="field" name="date" type="date" defaultValue={initialDate()} required/></Field><Field label="Note"><input className="field" name="note"/></Field></>}<FormActions busy={saving} onCancel={()=>{setModal(null);setActive(null)}}/></form></Modal>}
  </>
}

function WithdrawalsPage() {
  const {notify}=useApp();const [rows,setRows]=useState<any[]>([]);const [busy,setBusy]=useState(true);const [modal,setModal]=useState(false);const [saving,setSaving]=useState(false)
  const load=async()=>{setBusy(true);try{setRows(await api.get<any[]>('/api/withdrawals'))}catch(e){notify(errorText(e))}finally{setBusy(false)}}
  useEffect(()=>{void load()},[])
  const submit=async(e:React.FormEvent<HTMLFormElement>)=>{e.preventDefault();const f=new FormData(e.currentTarget);setSaving(true);try{await api.post('/api/withdrawals',{amount:Number(f.get('amount')),date:f.get('date'),reason:f.get('reason'),method:f.get('method')||null,note:f.get('note')||null,idempotencyKey:crypto.randomUUID()});notify('Owner withdrawal recorded separately from expenses');setModal(false);await load()}catch(err){notify(errorText(err))}finally{setSaving(false)}}
  return <><PageTitle eyebrow="Owner only" title="Owner withdrawals" subtitle="Withdrawals are separate from operating expenses and do not represent a reconciled bank balance." action={<button className="btn btn-primary" onClick={()=>setModal(true)}><Plus size={16}/> Record withdrawal</button>}/><Card>{busy?<Loading/>:rows.length?<DataTable columns={['Date','Reason','Method','Amount','Note']} rows={rows.map(w=>[date(w.date),w.reason,w.method||'—',money(w.amount),w.note||'—'])}/>:<Empty title="No withdrawals recorded" subtitle="Owner withdrawals will appear here, separate from operating expenses."/>}</Card>{modal&&<Modal title="Record owner withdrawal" onClose={()=>setModal(false)}><form onSubmit={submit} className="grid gap-4"><Field label="Amount (PKR)" required><input className="field" name="amount" type="number" min="0.01" step="0.01" required/></Field><Field label="Withdrawal date" required><input className="field" name="date" type="date" defaultValue={initialDate()} required/></Field><Field label="Reason" required><textarea className="field" name="reason" required maxLength={500}/></Field><Field label="Payment method"><input className="field" name="method"/></Field><Field label="Supporting note"><input className="field" name="note"/></Field><FormActions busy={saving} onCancel={()=>setModal(false)}/></form></Modal>}</>
}

function ReportsPage() {
  const {notify}=useApp();const [rows,setRows]=useState<any[]>([]);const [ledger,setLedger]=useState<any[]>([]);const [busy,setBusy]=useState(true);const [month,setMonth]=useState(new Date(new Date().getFullYear(),new Date().getMonth()-1,1).toISOString().slice(0,7));const [making,setMaking]=useState(false)
  const load=async()=>{setBusy(true);try{const [r,l]=await Promise.all([api.get<any[]>('/api/reports'),api.get<any[]>('/api/ledger?page=0&size=100')]);setRows(r);setLedger(l)}catch(e){notify(errorText(e))}finally{setBusy(false)}}
  useEffect(()=>{void load()},[])
  const generate=async()=>{setMaking(true);try{const result=await api.post<any>(`/api/reports?month=${month}`);notify(`Report for ${month} generated`);await load();if(result.id)await download(`/api/reports/${result.id}/download`,`indus-hostel-${month}.xlsx`)}catch(e){notify(errorText(e))}finally{setMaking(false)}}
  return <><PageTitle eyebrow="Owner reports" title="Monthly reports" subtitle="On the 5th, the prior calendar month is generated and emailed to the configured Owner address. Delivery attempts are tracked separately." action={<div className="flex gap-2"><input className="field w-auto" type="month" value={month} onChange={e=>setMonth(e.target.value)}/><button className="btn btn-primary" onClick={()=>void generate()} disabled={making}><FileSpreadsheet size={15}/>{making?'Generating…':'Generate report'}</button></div>}/>
    <div className="mb-5 rounded-xl border border-teal/15 bg-teal/5 p-4 text-sm leading-6 text-slate-600"><strong className="text-ink">Report contents:</strong> summary, fee status, paid and unpaid students, pending and rejected submissions, expense details, salary and advances, owner withdrawals, and room occupancy. Pending payments are clearly excluded from verified collections.</div>
    <Card><CardHead title="Report generation and delivery history"/>{busy?<Loading/>:rows.length?<DataTable columns={['Period','Generated','Type','Email delivery','Delivered','Error','Workbook']} rows={rows.map(r=>[dateMonth(r.reportingMonth),date(r.generatedAt),<Status value={r.generationKind}/>,<Status value={r.deliveryStatus}/>,date(r.deliveredAt),r.deliveryError||'—',<button className="btn btn-muted !px-2 !py-1" onClick={()=>download(`/api/reports/${r.id}/download`,`indus-hostel-${String(r.reportingMonth).slice(0,7)}.xlsx`).catch(e=>notify(errorText(e)))}><ArrowDownToLine size={14}/> Download</button>])}/>:<Empty title="No generated reports" subtitle="Generate a workbook or wait for the monthly scheduled run."/>}</Card>
    <Card className="mt-5"><CardHead title="Revenue and transaction ledger" subtitle="Collections, operating costs, advances, repayments, and withdrawals are explicit entries. Reversed entries stay visible for audit."/>{busy?<Loading/>:ledger.length?<DataTable columns={['Date','Entry type','Direction','Amount','Description','Recorded by','Status']} rows={ledger.map(l=>[date(l.occurredOn),l.entryType.replace(/_/g,' '),<Status value={l.direction}/>,money(l.amount),l.description,l.recordedBy,l.reversedAt?<Status value="REVERSED"/>:'—'])}/>:<Empty title="No ledger entries yet"/>}</Card>
  </>
}

function AccountsPage() {
  const {notify}=useApp();const [rows,setRows]=useState<any[]>([]);const [busy,setBusy]=useState(true);const [modal,setModal]=useState(false);const [saving,setSaving]=useState(false)
  const load=async()=>{setBusy(true);try{setRows(await api.get<any[]>('/api/users'))}catch(e){notify(errorText(e))}finally{setBusy(false)}}
  useEffect(()=>{void load()},[])
  const create=async(e:React.FormEvent<HTMLFormElement>)=>{e.preventDefault();const f=new FormData(e.currentTarget);setSaving(true);try{await api.post('/api/users',{email:f.get('email'),displayName:f.get('displayName'),role:'MANAGER',initialPassword:f.get('initialPassword')});notify('Manager account created');setModal(false);await load()}catch(err){notify(errorText(err))}finally{setSaving(false)}}
  const toggle=async(row:any)=>{if(!window.confirm(`${row.enabled?'Deactivate':'Reactivate'} account for ${row.email}?`))return;try{await api.put(`/api/users/${row.id}/status`,{enabled:!row.enabled});notify('Account access updated');await load()}catch(e){notify(errorText(e))}}
  return <><PageTitle eyebrow="Owner only" title="User access" subtitle="The system uses exactly three roles: Owner, Manager, and Student. Managers handle hostel operations; Students only see their own records." action={<button className="btn btn-primary" onClick={()=>setModal(true)}><Plus size={16}/> Add Manager account</button>}/><Card>{busy?<Loading/>:rows.length?<DataTable columns={['User','Role','Created','Status','Action']} rows={rows.map(r=>[<><strong>{r.displayName}</strong><div className="mt-1 text-[11px] text-slate-400">{r.email}</div></>,<Status value={r.role}/>,date(r.createdAt),r.enabled?<Status value="ACTIVE"/>:<Status value="INACTIVE"/>,r.role!=='OWNER'?<button className="btn btn-muted !px-2 !py-1" onClick={()=>void toggle(r)}>{r.enabled?'Deactivate':'Reactivate'}</button>:'Protected owner'])}/>:<Empty title="No accounts"/>}</Card>{modal&&<Modal title="Create Manager account" onClose={()=>setModal(false)}><form onSubmit={create} className="grid gap-4"><Field label="Display name" required><input className="field" name="displayName" required maxLength={160}/></Field><Field label="Email address" required><input className="field" name="email" type="email" required/></Field><Field label="Initial password (12+ characters)" required><input className="field" name="initialPassword" type="password" minLength={12} required/></Field><p className="text-xs text-slate-400">The password is hashed by the server before it is stored.</p><FormActions busy={saving} onCancel={()=>setModal(false)}/></form></Modal>}</>
}

function AuditPage() {
  const {notify}=useApp();const [rows,setRows]=useState<any[]>([]);const [busy,setBusy]=useState(true)
  useEffect(()=>{api.get<any[]>('/api/audit-logs?page=0&size=100').then(setRows).catch(e=>notify(errorText(e))).finally(()=>setBusy(false))},[])
  return <><PageTitle eyebrow="Owner oversight" title="Audit history" subtitle="Sensitive operations are recorded with the responsible account, timestamp, record, and reason where applicable."/><Card>{busy?<Loading/>:rows.length?<DataTable columns={['Time','User','Action','Record','Reason / details']} rows={rows.map(r=>[date(r.occurredAt),r.actor,<strong>{r.action.replace(/_/g,' ')}</strong>,`${r.entityType} ${r.entityId??''}`,r.reason||formatDetails(r.details)])}/>:<Empty title="No audit activity yet"/>}</Card></>
}

function SettingsPage() {
  const {branding,refreshBranding,notify}=useApp();const [name,setName]=useState(branding.hostelName);const [email,setEmail]=useState(branding.ownerEmail??'');const [busy,setBusy]=useState(false)
  useEffect(()=>{setName(branding.hostelName);api.get<Branding>('/api/settings').then(settings=>setEmail(settings.ownerEmail??'')).catch(e=>notify(errorText(e)))},[branding])
  const save=async(e:React.FormEvent)=>{e.preventDefault();setBusy(true);try{await api.put('/api/branding',{hostelName:name,ownerEmail:email||null,logoFileId:branding.logoFileId??null});await refreshBranding();notify('Hostel settings saved')}catch(err){notify(errorText(err))}finally{setBusy(false)}}
  const logo=async(file:File)=>{const data=new FormData();data.append('file',file);setBusy(true);try{await api.post('/api/branding/logo',data);await refreshBranding();notify('Official logo uploaded')}catch(err){notify(errorText(err))}finally{setBusy(false)}}
  return <><PageTitle eyebrow="Owner settings" title="Hostel branding & preferences" subtitle="The hostel name and logo are stored centrally and used in reports and payment receipts."/><div className="grid gap-5 xl:grid-cols-[1.2fr_.8fr]"><Card><CardHead title="Official identity" subtitle="Changes persist in the application database."/><form className="grid gap-4 p-5" onSubmit={save}><Field label="Official hostel name" required><input className="field" value={name} onChange={e=>setName(e.target.value)} required maxLength={160}/></Field><Field label="Owner email for scheduled report delivery"><input className="field" type="email" value={email} onChange={e=>setEmail(e.target.value)} placeholder="owner@example.com"/></Field><div className="flex justify-end"><button className="btn btn-primary" disabled={busy}>{busy?'Saving…':'Save settings'}</button></div></form></Card><Card><CardHead title="Official logo" subtitle="PNG, JPEG, or WebP up to 8 MB."/><div className="p-5"><div className="grid min-h-40 place-items-center rounded-xl border border-dashed border-slate-200 bg-slate-50 p-5">{branding.logoFileId?<img src={`${api.base}/api/files/${branding.logoFileId}`} alt="Current official hostel logo" className="max-h-40 max-w-full object-contain"/>:<div className="text-center"><div className="text-sm font-semibold text-slate-600">No logo file configured</div><p className="mt-1 max-w-xs text-xs leading-5 text-slate-400">The visual logo in the chat was not present as an image file beside the text brief. Upload the original file here to use it on receipts and reports.</p></div>}</div><label className="btn btn-muted mt-4 w-full">{branding.logoFileId?'Replace logo':'Upload original logo'}<input className="sr-only" type="file" accept="image/png,image/jpeg,image/webp" onChange={e=>e.target.files?.[0]&&logo(e.target.files[0])}/></label></div></Card></div><div className="mt-5 rounded-xl border border-amber-200 bg-amber-50 p-4 text-sm leading-6 text-amber-900"><strong>Configuration reminder:</strong> SMTP, database credentials, secure session cookies, trusted frontend origin, private storage, and the hostel time zone are configured in the backend environment.</div></>
}

function NotificationsPage() {
  const {notify}=useApp();const [rows,setRows]=useState<any[]>([]);const [busy,setBusy]=useState(true)
  const load=async()=>{setBusy(true);try{setRows(await api.get<any[]>('/api/notifications?page=0&size=100'))}catch(e){notify(errorText(e))}finally{setBusy(false)}}
  useEffect(()=>{void load()},[])
  const read=async(id:number)=>{try{await api.post(`/api/notifications/${id}/read`);await load()}catch(e){notify(errorText(e))}}
  return <><PageTitle eyebrow="Inbox" title="Notifications" subtitle="Private updates for this account. Student notifications are visible only to the signed-in Student." action={<button className="btn btn-muted" onClick={()=>void load()}><Activity size={15}/> Refresh</button>}/><Card>{busy?<Loading/>:rows.length?<div className="divide-y divide-slate-100">{rows.map(r=><div key={r.id} className="flex items-start justify-between gap-4 p-5"><div className="flex gap-3"><span className={`mt-1 h-2 w-2 rounded-full ${r.readAt?'bg-slate-200':'bg-teal'}`}/><div><div className="font-semibold text-ink">{r.title}</div><p className="mt-1 text-sm text-slate-500">{r.message}</p><div className="mt-2 text-[11px] text-slate-400">{date(r.createdAt)}</div></div></div>{!r.readAt&&<button className="btn btn-muted shrink-0 !px-2 !py-1" onClick={()=>void read(r.id)}>Mark read</button>}</div>)}</div>:<Empty title="You're all caught up" subtitle="Payment and due date reminders will appear here."/>}</Card></>
}

function formatDetails(value:unknown) { if(!value)return '—';try{return typeof value==='string'?JSON.stringify(JSON.parse(value)):JSON.stringify(value)}catch{return String(value)}}
